insert into public.experiences (id, name, category, description, lat, lng, area, price_kind, price_min, price_max, timing_kind, sessions, hours_text, duration_min, meeting_point, booking_required, booking_url, source, checked_on) values
  ('43934fe8-b004-9c98-3ab0-7a6caf3e4df1', 'Sketch and stroll', 'art_walks', 'Bring a sketchbook and walk the Shoal Creek trail at an easy pace. Stop at three spots to draw: the stone footbridge, the limestone ledges and the view back toward downtown. No drawing experience needed; pencils are shared.', 30.279, -97.751, 'Shoal Creek', 'free', 0, 0, 'flexible', null, 'Trail open daily, 5 AM to 10 PM', 90, 'Benches at the W 3rd St trailhead', false, null, 'PLACEHOLDER: wireframe sample, community listing (not a checked listing)', '2026-11-01'),
  ('0258d8ec-8559-0b6f-ca1f-c03205dae5f5', 'Clay and conversation', 'make', 'A beginner wheel-throwing session for small groups. An instructor walks you through centering and pulling one bowl each. Pieces are glazed by the studio and ready to pick up two weeks later.', 30.264, -97.722, 'East Austin', 'exact', 38, 38, 'fixed', '[{"label":"Sat 10:00 AM"},{"label":"Sat 1:00 PM"},{"label":"Sun 11:00 AM"}]'::jsonb, null, 90, 'Studio front desk', true, 'https://example.com/placeholder/clay', 'PLACEHOLDER: wireframe sample, venue website (not a checked listing)', '2026-11-01'),
  ('cd05dd62-f26b-909a-5044-55ddf7abee7a', 'Barton Springs swim', 'outdoors', 'A spring-fed pool that stays cool all year. Cold for the first minute, then perfect. Lifeguards on duty; bring a towel and a card for entry.', 30.2641, -97.7712, 'Zilker', 'estimated', 5, 9, 'flexible', null, 'Open most days; hours vary by season', 90, 'Main gate, south side of the lot', false, null, 'PLACEHOLDER: wireframe sample, city parks page (not a checked listing)', '2026-11-01'),
  ('8fe07fbd-8f62-3dd2-954b-576f67463902', 'Sunset kayak on Lady Bird Lake', 'outdoors', 'Guided paddle at golden hour from the rental dock, past the downtown skyline and back. Tandem boats available. No experience needed.', 30.261, -97.748, 'Downtown waterfront', 'estimated', 25, 25, 'fixed', '[{"label":"Fri 5:15 PM"},{"label":"Sat 5:15 PM"}]'::jsonb, null, 90, 'Dock check-in window', true, 'https://example.com/placeholder/kayak', 'PLACEHOLDER: wireframe sample, outfitter listing (not a checked listing)', '2026-11-01'),
  ('4e88a792-879a-8b87-a05c-f04833101736', 'Food truck crawl, East Cesar Chavez', 'food_drink', 'Walk four blocks of trailers and split plates: tacos, Thai, a dessert stop. Everyone pays at each truck.', 30.258, -97.726, 'East Cesar Chavez', 'estimated', 15, 25, 'flexible', null, 'Most trucks open 11 AM to late', 120, 'Corner of E Cesar Chavez and Chicon', false, null, 'PLACEHOLDER: wireframe sample, community listing (not a checked listing)', '2026-11-01'),
  ('f963ad6b-6932-4879-9f2d-8cc4a40601e7', 'Sunset at Mount Bonnell', 'outdoors', 'A short, steep set of stairs to one of the best views of the river. Go 30 minutes before sunset.', 30.3206, -97.7733, 'West Austin', 'free', 0, 0, 'flexible', null, 'Park open 5 AM to 10 PM', 45, 'Base of the stairs', false, null, 'PLACEHOLDER: wireframe sample, city parks page (not a checked listing)', '2026-11-01'),
  ('0b2d5dc7-f2fd-96b0-cda1-062d95ba5080', 'Tuesday trivia, Hyde Park', 'games_trivia', 'Pub trivia with teams of up to six. Five rounds, one picture round. Food and drinks are ordered at the bar.', 30.305, -97.729, 'Hyde Park', 'unknown', null, null, 'fixed', '[{"label":"Tue 7:30 PM"}]'::jsonb, null, 120, 'Back patio', false, null, 'PLACEHOLDER: wireframe sample, community listing (not a checked listing)', '2026-11-01'),
  ('04f05f2b-5b8c-a614-2297-84e6ef15ec51', 'Record dig on South Lamar', 'music_film', 'Hit three used-record shops in one stretch of South Lamar. Each person picks one record for someone else under $10.', 30.238, -97.786, 'South Lamar', 'unknown', null, null, 'flexible', null, 'Shops open around noon', 90, 'Outside the first shop', false, null, 'PLACEHOLDER: wireframe sample, community listing (not a checked listing)', '2026-11-01'),
  ('bb3c18c0-ad90-9000-3089-b275261a4f1b', 'Board game café afternoon', 'games_trivia', 'A wall of 600 games and staff who teach rules. Grab a big table for six.', 30.296, -97.743, 'North Campus', 'exact', 10, 10, 'flexible', null, 'Daily 11 AM to 11 PM', 150, 'Host stand', false, null, 'PLACEHOLDER: wireframe sample, venue website (not a checked listing)', '2026-11-01'),
