  ('3ee25c0d-90cf-3352-f108-41e7bad621d5', 'Mueller farmers market', 'food_drink', 'Sunday market by the lake with breakfast tacos, coffee and produce. Good for a slow morning walk.', 30.299, -97.705, 'Mueller', 'free', 0, 0, 'fixed', '[{"label":"Sun 10:00 AM to 2:00 PM"}]'::jsonb, null, 60, 'Info tent by the playground', false, null, 'PLACEHOLDER: wireframe sample, market website (not a checked listing)', '2026-11-01'),
  ('991de49a-dfae-b713-5461-c8aeee53412d', 'Rooftop film night', 'music_film', 'An outdoor screening on a downtown rooftop with blankets and headphones. This week: a 90s comedy double feature.', 30.265, -97.743, 'Downtown', 'exact', 15, 15, 'fixed', '[{"label":"Sat 7:30 PM"}]'::jsonb, null, 180, 'Lobby elevators', true, 'https://example.com/placeholder/rooftop-film', 'PLACEHOLDER: wireframe sample, venue website (not a checked listing)', '2026-11-01'),
  ('c36437a6-0f69-5f00-c63e-2743555a3b3e', 'Disc golf at Zilker', 'active', 'An easy, wooded nine-hole loop. Bring your own discs or borrow a starter set from a friend.', 30.265, -97.769, 'Zilker', 'free', 0, 0, 'flexible', null, 'Park open 5 AM to 10 PM', 90, 'Tee 1 near the lawn', false, null, 'PLACEHOLDER: wireframe sample, community listing (not a checked listing)', '2026-11-01'),
  ('bbe7a538-40fb-2d3c-be2a-e77cc4787de4', 'East Austin mural walk', 'art_walks', 'A self-guided loop past a dozen large murals. Stop for photos, trade favorites, and end with a coffee.', 30.262, -97.724, 'East Austin', 'free', 0, 0, 'flexible', null, 'Walk any time; best in daylight', 75, 'Corner of E 6th St and Chicon', false, null, 'PLACEHOLDER: invented (not a checked listing)', '2026-11-01'),
